import { test, expect } from '@playwright/test';

test.describe('Video Captions Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/videos');
  });

  test('should display captions when video is played', async ({ page }) => {
    const video = page.getByRole('video');
    await video.click();

    const captions = page.getByText('Caption text for the video');
    await expect(captions).toBeVisible();
  });

  test('should toggle captions on and off', async ({ page }) => {
    const video = page.getByRole('video');
    await video.click();

    const toggleCaptionsButton = page.getByRole('button', { name: 'Toggle Captions' });
    await toggleCaptionsButton.click();

    const captions = page.getByText('Caption text for the video');
    await expect(captions).not.toBeVisible();

    await toggleCaptionsButton.click();
    await expect(captions).toBeVisible();
  });
});
